{
  "status": "SUPPORTED",
  "task_summary": "Identify and fasten a component at a marked workbench location, then place the tool on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workbench",
        "entity_kind": "FIXED_TARGET",
        "function": "Provides the surface for the task and the final destination for the tool.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "bench"],
        "required_properties": ["stable", "horizontal"]
      },
      {
        "id": "assembly_target",
        "entity_kind": "OBJECT",
        "function": "The object at the marked location that requires fastening.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["device", "mechanism", "part"],
        "required_properties": ["has_fastening_point", "receives_component"]
      },
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "The physical part required to perform the fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screw", "bolt", "pin", "clip", "nut"],
        "required_properties": ["fits_target", "connects_parts"]
      },
      {
        "id": "fastening_equipment",
        "entity_kind": "OBJECT",
        "function": "The tool used to manipulate the component during fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "tool"],
        "required_properties": ["applies_force", "manipulates_component"]
      }
    ],
    "functional_relations": [
      {
        "id": "compatibility",
        "relation": "The compatible_component must suit the assembly_target to enable fastening.",
        "participant_roles": ["assembly_target", "compatible_component"]
      ,
        "required": true
      },
      {
        "id": "tool_usage",
        "relation": "The fastening_equipment acts upon the compatible_component and assembly_target.",
        "participant_roles": ["fastening_equipment", "compatible_component", "assembly_target"]
      ,
        "required": true
      },
      {
        "id": "final_placement",
        "relation": "The fastening_equipment must rest on the workbench after use.",
        "participant_roles": ["fastening_equipment", "workbench"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "fastening_task",
        "operation": "Use the fastening_equipment to attach the compatible_component to the assembly_target.",
        "participant_roles": ["fastening_equipment", "compatible_component", "assembly_target"],
        "operation_count": 1
      },
      {
        "id": "tool_deposition",
        "operation": "Place the fastening_equipment onto the workbench.",
        "participant_roles": ["fastening_equipment", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "workbench": [
        {
          "label": "wooden desk",
          "visual_description": "Wooden table surface with drawers."
        }
      ],
      "assembly_target": [
        {
          "label": "black tray with yellow object",
          "visual_description": "Rectangular black object with a yellow component on top, sitting on the desk."
        }
      ],
      "compatible_component": [],
      "fastening_equipment": []
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "blue cabinet",
        "visual_description": "Tall blue storage unit with a closed door behind the desk.",
        "reason": "Closed door suggests potential hiding place for compatible components or tools."
      },
      {
        "id": "under_desk_drawers",
        "label": "under desk drawers",
        "visual_description": "Two blue drawers beneath the desk surface.",
        "reason": "Closed drawers suggest potential hiding place for compatible components or tools."
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "under_desk_drawers"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
